    "question": "A 40-year-old-man presented to hospital with complaints of fever and weight loss. On examination, 102°F fever and anaemia were noted. Enlargement of liver and spleen were also present. The bone marrow aspirate collected was subjected to Giemsa staining which revealed amastigotes filled within a macrophage. a) Identify the etiological agent and the clinical diagnosis? b) Write about the life cycle & pathogenesis of the etiological agent. ¢) Describe the laboratory diagnosis of above condition.",
