    "topicKey": "bacteriology",
    "kind": "essay",
    "question": "A 25-year-old-man complains of mild fever, abdominal cramps, tenesmus, frequent passage of stools associated with blood and mucus. Stool microscopy shows abundant pus cells and no ova/cysts/trophozoites were seen. Stool culture yielded the growth of non-lactose fermenters. a) What is the etiological agent causing above clinical condition? b) Describe the pathogenesis and complications of the above clinical condition c) Describe the laboratory diagnosis of the above clinical condition",
